mapper.update:
UPDATE stock_sync_progress
SET status = 'RUNNING', started_at = NOW()
WHERE stock_id = #{stockId} AND job_type = #{jobType}

UPDATE stock_sync_progress
SET status = 'DONE', last_synced_date = #{lastSyncedDate}, finished_at = NOW()
WHERE stock_id = #{stockId} AND job_type = #{jobType}

UPDATE stock_sync_progress
SET status = 'FAILED', attempt_count = attempt_count + 1, last_error = #{lastError}, finished_at = NOW()
WHERE stock_id = #{stockId} AND job_type = #{jobType}

UPDATE stock_sync_progress
SET status = 'SKIPPED', finished_at = NOW()
WHERE stock_id = #{stockId} AND job_type = #{jobType}

UPDATE stock_sync_progress
SET status = 'SKIPPED', last_synced_date = #{lastSyncedDate}, finished_at = NOW()
WHERE stock_id = #{stockId} AND job_type = #{jobType}
